#include <map>
#include <string>
#include <vector>

std::vector<unsigned long long> fillIat(const std::vector<std::string>& imports,
                                        const std::map<std::string, unsigned long long>& exportRvas,
                                        unsigned long long dllBase)
{
    std::vector<unsigned long long> slots;
    for (const std::string& name : imports)
    {
        const auto it{ exportRvas.find(name) };
        slots.push_back(it == exportRvas.end() ? 0ULL : dllBase + it->second);
    }
    return slots;
}

unitTests:
using Rvas = std::map<std::string, unsigned long long>;
using Slots = std::vector<unsigned long long>;
TEST("the example") { CHECK_EQ(fillIat({ "stackHeight", "stackWeight" }, Rvas{ {"stackHeight", 0x1023}, {"stackWeight", 0x10A5} }, 0x7FFA10000000ULL), (Slots{ 0x7FFA10001023ULL, 0x7FFA100010A5ULL })); }
TEST("missing export gives 0") { CHECK_EQ(fillIat({ "a", "b" }, Rvas{ {"a", 0x10} }, 0x1000ULL), (Slots{ 0x1010ULL, 0ULL })); }
TEST("order follows the imports") { CHECK_EQ(fillIat({ "z", "a" }, Rvas{ {"a", 1}, {"z", 2} }, 100ULL), (Slots{ 102ULL, 101ULL })); }
TEST("nothing imported") { CHECK(fillIat({}, Rvas{ {"a", 1} }, 100ULL).empty()); }

